import React from 'react';
import { Stack, Typography } from '@mui/material';
import { formatCo2eFromKg } from '../../constants/carbonVisualization';

export type GhgInventoryCategory = {
  key: string;
  label: string;
  kgCo2e: number;
  status?: string;
  gap?: string | null;
  isoPlacement?: string | null;
};

export type GhgInventoryMeasurementProps = {
  scope2Dual?: {
    locationBasedKg?: number;
    marketBasedKg?: number;
    deltaKg?: number;
    marketInstrumentsPresent?: boolean;
  } | null;
  uncertainty?: {
    combinedRelativeUncertainty?: number | null;
    combinedAbsoluteUncertaintyKg?: number | null;
    lowerBoundKg?: number | null;
    upperBoundKg?: number | null;
    confidenceLevel?: number | null;
  } | null;
  biogenicCo2Kg?: number | null;
  categories?: GhgInventoryCategory[];
};

const toSafe = (value: unknown): number => {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
};

const GhgInventoryMeasurement: React.FC<GhgInventoryMeasurementProps> = ({
  scope2Dual,
  uncertainty,
  biogenicCo2Kg,
  categories = [],
}) => {
  const register = categories.filter((row) => row.key !== 'unclassified_indirect');
  const relative = uncertainty?.combinedRelativeUncertainty;
  const uncertaintyPercent = relative == null || !Number.isFinite(Number(relative))
    ? null
    : Math.round(Number(relative) * 10000) / 100;
  const showMeasurement = Boolean(scope2Dual) || uncertaintyPercent != null || biogenicCo2Kg != null;

  if (!showMeasurement && register.length === 0) {
    return null;
  }

  return (
    <Stack spacing={1.25} data-testid="ghg-inventory-measurement">
      {showMeasurement ? (
        <Stack spacing={0.5}>
          <Typography variant="body2" sx={{ fontWeight: 600 }}>
            Measured inventory
          </Typography>
          {scope2Dual ? (
            <Typography variant="caption" color="text.secondary" display="block">
              Scope 2 location-based {formatCo2eFromKg(toSafe(scope2Dual.locationBasedKg))}
              {' · '}
              market-based {formatCo2eFromKg(toSafe(scope2Dual.marketBasedKg))}
              {' · '}
              difference {formatCo2eFromKg(toSafe(scope2Dual.deltaKg))}
              {scope2Dual.marketInstrumentsPresent
                ? '. Renewable instruments are stored.'
                : '. No renewable instrument is stored, so market-based Scope 2 stays with the location-based total.'}
            </Typography>
          ) : null}
          {uncertaintyPercent != null ? (
            <Typography variant="caption" color="text.secondary" display="block">
              {`Combined uncertainty ${uncertaintyPercent}%${
                uncertainty?.combinedAbsoluteUncertaintyKg != null
                  ? ` (${formatCo2eFromKg(toSafe(uncertainty.combinedAbsoluteUncertaintyKg))} absolute${
                    uncertainty?.lowerBoundKg != null && uncertainty?.upperBoundKg != null
                      ? `, range ${formatCo2eFromKg(toSafe(uncertainty.lowerBoundKg))} to ${formatCo2eFromKg(toSafe(uncertainty.upperBoundKg))}`
                      : ''
                  })`
                  : ''
              }${uncertainty?.confidenceLevel != null ? ` at confidence ${uncertainty.confidenceLevel}` : ''}.`}
            </Typography>
          ) : null}
          {biogenicCo2Kg != null ? (
            <Typography variant="caption" color="text.secondary" display="block">
              Biogenic CO₂ {formatCo2eFromKg(toSafe(biogenicCo2Kg))}, reported separately and not added to the fossil total.
            </Typography>
          ) : null}
        </Stack>
      ) : null}
      {register.length > 0 ? (
        <Stack spacing={0.5}>
          <Typography variant="body2" sx={{ fontWeight: 600 }}>
            All 15 GHG Protocol Scope 3 categories
          </Typography>
          <Typography variant="caption" color="text.secondary" display="block">
            Each line is the GHG Protocol category, the ISO 14064-1 category it is measured in, and the kilograms stored for it.
          </Typography>
          {register.map((row) => (
            <Stack key={row.key} direction="row" spacing={1} justifyContent="space-between" alignItems="baseline" sx={{ minWidth: 0 }}>
              <Typography variant="caption" color="text.secondary" sx={{ minWidth: 0, pr: 1 }}>
                {row.label}
                {row.isoPlacement ? ` — ${row.isoPlacement}` : ''}
                {toSafe(row.kgCo2e) <= 0 && row.gap ? ` — ${row.gap}` : ''}
              </Typography>
              <Typography variant="caption" sx={{ fontWeight: 600, whiteSpace: 'nowrap', flexShrink: 0 }}>
                {toSafe(row.kgCo2e) > 0 ? formatCo2eFromKg(toSafe(row.kgCo2e)) : '0 kg CO₂e'}
              </Typography>
            </Stack>
          ))}
        </Stack>
      ) : null}
    </Stack>
  );
};

export default GhgInventoryMeasurement;
